<script setup>
import {computed,onMounted,reactive,ref} from "vue";import {ArrowDownToLine,ArrowUpFromLine,Printer} from "@lucide/vue";import AdminLayout from "../components/admin/AdminLayout.vue";import AppModal from "../components/AppModal.vue";import AsyncButton from "../components/AsyncButton.vue";import CurrencyInput from "../components/CurrencyInput.vue";import FormField from "../components/FormField.vue";import SelectInput from "../components/SelectInput.vue";import TextareaInput from "../components/TextareaInput.vue";import {apiFetch} from "../services/api";import {toast} from "../services/toast";import {t} from "../services/i18n";
const shift=ref(null),loading=ref(true),modal=ref(""),saving=ref(false),receipt=ref(null);const form=reactive({cash:0,note:"",category:""});const money=v=>new Intl.NumberFormat("id-ID",{style:"currency",currency:"IDR",maximumFractionDigits:0}).format(v||0);const movementType=computed(()=>modal.value==="cash_in"?"cash_in":"cash_out");const categories=computed(()=>movementType.value==="cash_in"?[{value:"additional_capital",label:t("cash.additional_capital")},{value:"other",label:t("cash.other")}]:[{value:"operational",label:t("cash.operational")},{value:"store_supplies",label:t("cash.store_supplies")},{value:"cash_withdrawal",label:t("cash.cash_withdrawal")},{value:"other",label:t("cash.other")}]);
async function load(){loading.value=true;try{shift.value=(await apiFetch("/api/v1/admin/cashier_shifts/current")).cashier_shift}finally{loading.value=false}}function show(type){modal.value=type;form.cash=type==="close"?(shift.value?.cash_summary?.expected_cash||0):0;form.note="";form.category=type==="cash_in"?"additional_capital":type==="cash_out"?"operational":""}
async function submitShift(){saving.value=true;try{const opening=modal.value==="open",body=opening?{opening_cash:form.cash,opening_note:form.note}:{actual_cash:form.cash,closing_note:form.note},url=opening?"/api/v1/admin/cashier_shifts":`/api/v1/admin/cashier_shifts/${shift.value.id}/close`;await apiFetch(url,{method:opening?"POST":"PATCH",body:JSON.stringify(body)});toast.success(t(opening?"shift.opened":"shift.closed"));modal.value="";await load()}catch(e){toast.error(e.message)}finally{saving.value=false}}
async function submitMovement(){saving.value=true;try{const r=await apiFetch(`/api/v1/admin/cashier_shifts/${shift.value.id}/cash_movement`,{method:"POST",body:JSON.stringify({movement_type:movementType.value,amount:form.cash,category:form.category,note:form.note})});receipt.value={...r.cash_movement,shift_number:shift.value.shift_number};shift.value=r.cashier_shift;modal.value="";toast.success(t("cash.saved"))}catch(e){toast.error(e.message)}finally{saving.value=false}}const categoryLabel=key=>t(`cash.${key}`),printReceipt=()=>window.print();onMounted(load);
</script>
<template><AdminLayout><div class="mx-auto max-w-6xl"><h1 class="text-2xl font-semibold dark:text-white">{{t('shift.my_title')}}</h1><div v-if="loading" class="mt-6">{{t('common.loading_data')}}</div><template v-else-if="shift"><section class="mt-6 rounded-2xl border bg-white p-5 dark:bg-gray-900"><div class="flex flex-wrap items-center justify-between gap-4"><div><h2 class="font-semibold">{{t('shift.active')}}</h2><p class="text-sm text-gray-500">{{shift.shift_number}}</p></div><div class="flex flex-wrap gap-2"><AsyncButton class="rounded-lg bg-success-600 px-4 py-2.5 text-white" @click="show('cash_in')"><ArrowDownToLine :size="17"/>{{t('cash.in')}}</AsyncButton><AsyncButton class="rounded-lg bg-warning-500 px-4 py-2.5 text-white" @click="show('cash_out')"><ArrowUpFromLine :size="17"/>{{t('cash.out')}}</AsyncButton><AsyncButton class="rounded-lg bg-error-600 px-4 py-2.5 text-white" @click="show('close')">{{t('shift.close')}}</AsyncButton></div></div><dl class="mt-5 grid grid-cols-2 gap-3 md:grid-cols-3 lg:grid-cols-6"><div v-for="row in [[t('shift.opening_cash'),shift.cash_summary.opening_cash],[t('cash.sales'),shift.cash_summary.cash_sales],[t('cash.refunds'),-shift.cash_summary.cash_refunds],[t('cash.in'),shift.cash_summary.cash_in],[t('cash.out'),-shift.cash_summary.cash_out],[t('cash.expected'),shift.cash_summary.expected_cash]]" :key="row[0]" class="rounded-xl bg-gray-50 p-3 dark:bg-gray-800"><dt class="text-xs text-gray-500">{{row[0]}}</dt><dd class="mt-1 font-bold" :class="row[1]<0?'text-error-600':''">{{money(row[1])}}</dd></div></dl></section><section class="mt-5 rounded-2xl border bg-white p-5 dark:bg-gray-900"><h2 class="font-semibold">{{t('cash.history')}}</h2><p v-if="!shift.cash_movements.length" class="py-8 text-center text-sm text-gray-500">{{t('cash.empty')}}</p><div v-else class="mt-4 divide-y"><div v-for="m in shift.cash_movements" :key="m.id" class="flex items-center justify-between gap-4 py-3"><div><p class="font-medium">{{categoryLabel(m.category)}}</p><p class="text-xs text-gray-500">{{m.note}} · {{new Date(m.created_at).toLocaleString()}}</p></div><strong :class="m.amount<0?'text-error-600':'text-success-600'">{{m.amount>0?'+':''}}{{money(m.amount)}}</strong></div></div></section></template><div v-else class="mt-6 rounded-2xl border bg-white p-8 text-center dark:bg-gray-900"><p>{{t('shift.no_active')}}</p><AsyncButton class="mt-5 rounded-lg bg-brand-500 px-5 py-2.5 text-white" @click="show('open')">{{t('shift.open')}}</AsyncButton></div></div>
<AppModal :open="['open','close'].includes(modal)" :title="t(modal==='open'?'shift.open':'shift.close')" :close-disabled="saving" size="lg" @close="modal='' "><form id="shift-form" class="space-y-5" @submit.prevent="submitShift"><FormField :label="t(modal==='open'?'shift.opening_cash':'shift.actual_cash')"><CurrencyInput v-model="form.cash"/></FormField><FormField :label="t('shift.note')"><TextareaInput v-model="form.note" rows="3"/></FormField></form><template #footer><button @click="modal=''">{{t('common.cancel')}}</button><AsyncButton form="shift-form" type="submit" :loading="saving" class="rounded-lg bg-brand-500 px-5 py-2.5 text-white">{{t('common.save')}}</AsyncButton></template></AppModal>
<AppModal :open="['cash_in','cash_out'].includes(modal)" :title="t(modal==='cash_in'?'cash.in':'cash.out')" :close-disabled="saving" @close="modal='' "><form id="movement-form" class="space-y-4" @submit.prevent="submitMovement"><FormField :label="t('cash.amount')"><CurrencyInput v-model="form.cash"/></FormField><FormField :label="t('cash.category')"><SelectInput v-model="form.category"><option v-for="item in categories" :key="item.value" :value="item.value">{{item.label}}</option></SelectInput></FormField><FormField :label="t('shift.note')"><TextareaInput v-model="form.note" rows="3" required/></FormField><p v-if="modal==='cash_out'" class="text-sm text-gray-500">{{t('cash.available')}}: <b>{{money(shift.cash_summary.expected_cash)}}</b></p></form><template #footer><button @click="modal=''">{{t('common.cancel')}}</button><AsyncButton form="movement-form" type="submit" :loading="saving" :disabled="form.cash<=0||!form.note.trim()" class="rounded-lg bg-brand-500 px-5 py-2.5 text-white">{{t('common.save')}}</AsyncButton></template></AppModal>
<AppModal :open="Boolean(receipt)" :title="t('cash.receipt')" @close="receipt=null"><article v-if="receipt" class="thermal-cash receipt-58 mx-auto bg-white p-3 font-mono text-xs text-black"><h2 class="text-center text-base font-bold">{{t('cash.receipt')}}</h2><p class="text-center">{{receipt.shift_number}}<br/>{{new Date(receipt.created_at).toLocaleString()}}</p><hr class="my-2"/><div class="flex justify-between"><span>{{receipt.movement_type==='cash_in'?t('cash.in'):t('cash.out')}}</span><b>{{money(Math.abs(receipt.amount))}}</b></div><p>{{categoryLabel(receipt.category)}}</p><p>{{receipt.note}}</p></article><template #footer><AsyncButton class="rounded bg-brand-500 px-4 py-2 text-white" @click="printReceipt"><Printer :size="16"/>{{t('pos.print')}}</AsyncButton></template></AppModal></AdminLayout></template>
<style>.receipt-58{width:58mm}@media print{body *{visibility:hidden!important}.thermal-cash,.thermal-cash *{visibility:visible!important}.thermal-cash{position:fixed;inset:0 auto auto 0}}</style>
